public class DateTimeFormatter_parseInto_TriageGen0Test {

    @Test(expected = IllegalArgumentException.class)
    public void testParseInto_NullInstant_ThrowsException() {
        DateTimeFormatter formatter = DateTimeFormat.forPattern("yyyy-MM-dd").getParser();
        formatter.parseInto(null, "2023-01-01", 0);
    }

    @Test
    public void testParseInto_StandardDate_UpdatesInstant() {
        // Using a standard pattern to ensure the parser is valid
        DateTimeFormatter formatter = DateTimeFormat.forPattern("yyyyMMdd").getParser();
        ReadWritableInstant instant = new ReadWritableInstant(new org.joda.time.DateTime(2000, 1, 1, 0, 0));

        String text = "20231025";
        int position = 0;

        int newPos = formatter.parseInto(instant, text, position);

        // Check if the position moved (for yyyyMMdd, it should consume the whole string)
        assertEquals(8, newPos);
        // Check if the instant was updated to Oct 25, 2023
        assertEquals(2023, instant.getChronology().year().get(instant.getMillis()));
        assertEquals(10, instant.getChronology().month().get(instant.getMillis()));
        assertEquals(25, instant.getChronology().dayOfMonth().get(instant.getMillis()));
    }

    @Test
    public void testParseInto_WithOffsetParsed_UpdatesZone() {
        // Pattern with offset to trigger iOffsetParsed logic
        DateTimeFormatter formatter = DateTimeFormat.forPattern("yyyy-MM-dd HH:mm Z")
                .withOffsetParsed()
                .getParser();

        ReadWritableInstant instant = new ReadWritableInstant(new org.joda.time.DateTime(2023, 1, 1, 0, 0));
        String text = "2023-01-01 12:00 +0500";

        formatter.parseInto(instant, text, 0);

        // The zone should be updated to +05:00
        assertEquals("+05:00", instant.getZone().getID());
    }

    @Test
    public void testParseInto_WithExplicitZone_MaintainsZone() {
        DateTimeZone targetZone = DateTimeZone.forID("America/New_York");
        DateTimeFormatter formatter = DateTimeFormat.forPattern("yyyy-MM-dd")
                .withZone(targetZone)
                .getParser();

        ReadWritableInstant instant = new ReadWritableInstant(new org.joda.time.DateTime(2023, 1, 1, 0, 0));
        String text = "2023-01-01";

        formatter.parseInto(instant, text, 0);

        // Even if parsed, the explicit zone set via withZone should be applied
        assertEquals(targetZone, instant.getZone());
    }

    @Test
    public void testParseInto_WithPivotYear() {
        // Use a 2-digit year to test pivot year logic
        DateTimeFormatter formatter = DateTimeFormat.forPattern("yy-MM-dd")
                .withPivotYear(2000)
                .getParser();

        ReadWritableInstant instant = new ReadWritableInstant(new org.joda.time.DateTime(2000, 1, 1, 0, 0));
        String text = "23-01-01"; // 2023

        formatter.parseInto(instant, text, 0);

        assertEquals(2023, instant.getChronology().year().get(instant.getMillis()));
    }

    /**
     * Helper class to mock/implement ReadWritableInstant behavior 
     * since it's an interface often used in Joda-Time internals.
     */
    private static class ReadWritableInstant implements org.joda.time.ReadableInstant {
        private long millis;
        private Chronology chronology;
        private DateTimeZone zone;

        public ReadWritableInstant(org.joda.time.DateTime dt) {
            this.millis = dt.getMillis();
            this.chronology = dt.getChronology();
            this.zone = dt.getZone();
        }

        public long getMillis() { return millis; }
        public void setMillis(long millis) { this.millis = millis; }
        public Chronology getChronology() { return chronology; }
        public void setChronology(Chronology chronology) { this.chronology = chronology; }
        public DateTimeZone getZone() { return zone; }
        public void setZone(DateTimeZone zone) { this.zone = zone; }

        @Override
        public DateTimeZone getOffset(org.joda.time.ReadableInstant instant) {
            return zone;
        }
    }
}
